mapper.select:
SELECT P.PRODUCT_NO, P.PRODUCT_NAME, P.BRAND, P.PRODUCT_PRICE, P.STOCK_QTY, P.PRODUCT_STATUS, DATE_FORMAT(P.CDATE, '%Y-%m-%d %H:%i:%s') AS CDATE, AM.A_MAIN_NO, AM.A_MAIN_TYPE, ASUB.A_SUB_NO, ASUB.A_SUB_TYPE, IM.I_MAIN_NO, IM.I_MAIN_TYPE, ISUB.I_SUB_NO, ISUB.I_SUB_TYPE, CONCAT(F.FILE_PATH, F.FILE_NAME) AS MAIN_IMG FROM PRODUCT P LEFT JOIN PC_ANIMAL_SUB ASUB ON P.A_SUB_NO = ASUB.A_SUB_NO LEFT JOIN PC_ANIMAL_MAIN AM ON ASUB.A_MAIN_NO = AM.A_MAIN_NO LEFT JOIN PC_ITEM_SUB ISUB ON P.I_SUB_NO = ISUB.I_SUB_NO LEFT JOIN PC_ITEM_MAIN IM ON ISUB.I_MAIN_NO = IM.I_MAIN_NO LEFT JOIN PRODUCT_FILE F ON P.PRODUCT_NO = F.PRODUCT_NO AND F.IS_MAIN = 'Y' WHERE 1 = 1 AND P.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')
AND AM.A_MAIN_NO = #{aMainNo}
AND ASUB.A_SUB_NO = #{aSubNo}
AND IM.I_MAIN_NO = #{iMainNo}
AND ISUB.I_SUB_NO = #{iSubNo}
ORDER BY P.PRODUCT_PRICE ASC
ORDER BY P.PRODUCT_PRICE DESC
ORDER BY P.PRODUCT_NO DESC

mapper.update:
UPDATE CART
SET QTY = #{qty}
WHERE CART_NO = #{cartNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM CART
WHERE CART_NO = #{cartNo}
AND USER_ID = #{userId}

mapper.update:
UPDATE CART
SET QTY = QTY + #{qty}
WHERE USER_ID = #{userId}
AND PRODUCT_NO = #{productNo}

mapper.select:
SELECT COUNT(*)
FROM CART
WHERE USER_ID = #{userId}

